// Package outputschema names the published JSON Schemas that describe what each
// command prints under --json. The schemas themselves are generated by
// tools/schemagen from the types each command package declares in OutputTypes.
package outputschema

import "strings"

// BaseURL is where the generated schemas are published.
const BaseURL = "https://sergiught.github.io/openfga-cli/schemas/output/"

// EnvelopePath is the pseudo command path of the error envelope; its schema is
// error.v1.json.
const EnvelopePath = "error"

// Handwritten marks an output whose schema is a hand-written file under
// tools/schemagen/handwritten/<FileName(path)> (used for map[string]any outputs
// and outputs that vary by mode, such as --dry-run).
type Handwritten struct{}

// FileName maps a command path to its schema file name:
// "ofga tuples write" -> "tuples-write.v1.json".
func FileName(path string) string {
	path = strings.TrimPrefix(path, "ofga ")
	return strings.ReplaceAll(path, " ", "-") + ".v1.json"
}

// URL is the published address, and the $id, of a command's schema.
func URL(path string) string { return BaseURL + FileName(path) }
